// Turns the SOURCES tab the pitching engine already maintains into CrowdRelay
// candidates. It imports what the band worked out by hand; it does not decide
// who may be contacted — screening on the CrowdRelay side still does that, and
// an operator still confirms every route before it becomes a target.
//
// Two rules keep this honest:
//
//  - `route_is_published` is true only where the row actually records a route.
//    An import is a route that was *read from a record*, never one worked out
//    from a name and a domain, so a blank cell is skipped rather than guessed.
//  - Anyone the submission log says was already pitched is counted and
//    reported. CrowdRelay must not be handed a contact as though it were fresh
//    when somebody already used the band's one first approach on them.

function clean(v) { return String(v === undefined || v === null ? '' : v).trim(); }
function truth(v) { return ['TRUE','YES','TAK','1'].includes(clean(v).toUpperCase()); }
function isEmail(v) { return /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(clean(v).toLowerCase()); }
function rows(node) { try { return $(node).all().map(i => i.json || {}); } catch (e) { return []; } }

const KIND = {
  playlist: 'playlist', radio: 'radio', press: 'press', blog: 'press',
  magazine: 'press', creator: 'creator', youtube: 'creator', podcast: 'creator'
};

// Everyone the band has already pitched, by contact identity.
const contacted = new Set();
for (const log of rows('GS — SUBMISSION_LOG')) {
  const key = clean(log.Contact_Email || log.Source_ID).toLowerCase();
  if (key) contacted.add(key);
}

const candidates = [];
const skipped = { inactive: 0, no_route: 0, already_pitched: 0 };

for (const row of rows('GS — SOURCES')) {
  const sourceId = clean(row.Source_ID);
  if (!sourceId) continue;
  if (!truth(row.Active)) { skipped.inactive += 1; continue; }

  const email = clean(row.Contact_Email);
  const form = clean(row.Submission_URL);
  let route_kind = null, route_value = null;
  if (isEmail(email)) { route_kind = 'email'; route_value = email.toLowerCase(); }
  else if (/^https?:\/\//i.test(form)) { route_kind = 'submission_form'; route_value = form; }
  // No recorded route means no route. Never derive one from the name.
  if (!route_value) { skipped.no_route += 1; continue; }

  const seen = contacted.has(route_value) || contacted.has(sourceId.toLowerCase());
  if (seen) skipped.already_pitched += 1;

  const platform = clean(row.Platform).toLowerCase();
  candidates.push({
    target_kind: KIND[platform] || 'playlist',
    display_name: (clean(row.Source_Name) || sourceId).slice(0, 200),
    source: 'operator_import',
    source_reference: ('sheet:' + $env.VIRYA_PITCHING_SHEET_ID + '#SOURCES:' + sourceId).slice(0, 2048),
    // The provenance IS the evidence for an import: which record this route was
    // read out of, so a human can check it later without guessing.
    evidence: ('Operator import from the playlist pitching sheet, SOURCES row '
      + sourceId + '. Platform: ' + (clean(row.Platform) || 'unknown')
      + '. Recorded action class: ' + (clean(row.Action_Class) || 'unset')
      + '. Free channel: ' + (truth(row.Free) ? 'yes' : 'no')
      + (seen ? '. Already pitched at least once by the sheet-driven engine.' : '')).slice(0, 4000),
    route_kind,
    route_value: route_value.slice(0, 2048),
    route_is_published: true,
    fit_basis_points: Number($env.VIRYA_IMPORT_FIT_BASIS_POINTS || 7000),
    follower_count: null,
    engagement_count: null,
    // A channel that is not free is spend, and CrowdRelay decides that from the
    // channel, not from us. Placement-selling is a separate claim we cannot
    // make from a spreadsheet, so it stays false rather than guessed.
    sells_placement: false,
    churns_indiscriminately: false
  });
}

// Dedupe on contact identity: the same curator listed twice is one candidate.
const seenRoute = new Set();
const unique = candidates.filter(c => {
  const key = c.route_kind + ':' + c.route_value.toLowerCase();
  if (seenRoute.has(key)) return false;
  seenRoute.add(key); return true;
});

// Batches of 100, because that is the bound the ingest route enforces.
const batches = [];
for (let i = 0; i < unique.length; i += 100) batches.push(unique.slice(i, i + 100));

return [{ json: {
  commit: truth($env.VIRYA_IMPORT_COMMIT),
  total: unique.length,
  skipped,
  batches,
  preview: unique.slice(0, 5).map(c => ({ name: c.display_name, route: c.route_kind }))
}}];

// Dry run by default. An import that writes on its first execution gives
// nobody a chance to read what it matched, and a wrong mapping is far cheaper
// to find here than in a queue of contacts nobody recognises.
const r = $json;
const lines = [
  '**VIRYA — import kontaktow z arkusza pitchingu**',
  '',
  r.commit ? 'Tryb: ZAPIS do CrowdRelay' : 'Tryb: PROBNY (nic nie zapisano)',
  'Do zaimportowania: ' + r.total,
  'Pominiete — nieaktywne: ' + r.skipped.inactive,
  'Pominiete — brak zapisanej sciezki kontaktu: ' + r.skipped.no_route,
  'Juz pitchowane wczesniej: ' + r.skipped.already_pitched,
  '',
  'Przyklady: ' + r.preview.map(p => p.name + ' (' + p.route + ')').join(', ')
];
if (!r.commit) lines.push('', 'Ustaw VIRYA_IMPORT_COMMIT=TRUE i uruchom ponownie, aby zapisac.');
return [{ json: { content: lines.join('\n').slice(0, 1900) } }];
